import * as React from "react";

export type MixerDialsIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function MixerDialsIcon({ size = 20, ...props }: MixerDialsIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="4" y="6" width="16" height="12" rx="1.5" /><circle cx="9" cy="12" r="1.8" /><circle cx="15" cy="12" r="1.8" />
    </svg>
  );
}
